    if (qn.w < 0.0) {
        qn.w = -qn.w;
        qn.x = -qn.x;
        qn.y = -qn.y;
        qn.z = -qn.z;
    }
    *accepted = qn;
    *separation_rad = 0.0;
    qc_state.previous = qn;
    qc_state.initialized = 1;
    return ADCS_OK;
}

