{
    adcs_quat_t hist = qc_state.previous;
    double dot = qn.w * hist.w + qn.x * hist.x + qn.y * hist.y + qn.z * hist.z;
    double d;
    if (dot < 0.0) {
        qn.w = -qn.w;
        qn.x = -qn.x;
        qn.y = -qn.y;
        qn.z = -qn.z;
    }
    *accepted = qn;
    d = adcs_quat_abs_dot(&qn, &hist);
    if (d > 1.0) d = 1.0;
    if (d < 0.0) d = 0.0;
    *separation_rad = 2.0 * acos(d);
    qc_state.previous = qn;
    return ADCS_OK;
}

